L000131	    \centering
L000132	     \makebox[\textwidth][c]{
L000133	\includegraphics[width=\textwidth]{final_figures/panel2.pdf}}
L000134	     \caption{
L000135	     \textbf{Pitchfork bifurcation to an active droplet:}
L000136	
L000137	     (a) Upon increasing the fuel strength $\delta$, the reaction nullcline (Eq.~\eqref{eq:NESS}) for reaction $r_1$ (Eq.~\eqref{eq:r_1_pathway}) in the phase-separated domain (gray shaded) bends, leading to three non-equilibrium steady states (NESS) for a fixed conservation line $\bar{\psi}=\bar{\phi}_A+\bar{\phi}_B$; closed symbols are stable and open symbols unstable fixed points.
L000138	
L000139	     (b) The net reaction rate along the conservation line only has multiple steady states for sufficiently large fuel strength $\delta/(k_BT)$, where the center point is unstable.
L000140	
L000141	     (c) The multiple steady points arise from a pitchfork bifurcation in droplet volume upon a critical fuel strength $\delta^*$ (vertical dotted line). Above this threshold value  $\delta^*$, there are three NESS' where two are locally stable (bistability).
L000142	
L000143	     (d)
L000144	      At fixed fuel strength,
L000145	     The occurrence of the bifurcation depends on the value of quantity $\bar{\psi}$ conserved by reaction~\eqref{eq:r_1_pathway}. There is a range of  $\bar{\psi}$-values (vertical dotted lines), where the system is bistable.
L000146	
L000147	     (e)
L000148	     Bistability is only possible within a range of $\bar{\psi}$ values that grow with fuel strength $\delta$. The analytical approximation for the critical fuel strength $\delta^*$ from Eq.~\eqref{eq:full_delta*} agrees well for fuel strength $\delta$ close to the onset of bistability.}
L000149	     \label{fig:2}
L000150	\end{figure*}
L000151	
L000152	\textit{Theory of active droplets:}
L000153	The evolution of volume fractions $\phi_i(\bm{x}, t)$ in space $\bm{x}$ and time $t$ are governed by diffusive fluxes $\bm{j}_i$ and reaction rates $r_i$ of component $i$ with the corresponding continuous equations~\cite{julicherDropletPhysicsIntracellular2024, bauermannEnergyMatterSupply2022d,weberPhysicsActiveEmulsions2019d}:
L000154	\begin{equation}   \partial_t\phi_i(\bm{x}, t) =  -\nabla \cdot \bm{j}_i + r_i\,  .\label{eq:phi_dot}
L000155	\end{equation}
L000156	We investigate a minimalistic ternary system $(i=A,B,C)$ initially limited to a single reversible uni-molecular chemical reaction between $A$ and $B$,
L000157	\begin{equation}
L000158	r_1: \quad \ce{A <=>>[$k_1\exp{\tilde{\delta}/(k_BT)}$][$k_1$]B} \, ,\label{eq:r_1_pathway}
L000159	\end{equation}
L000160	where the net reaction rate $r_B=-r_A= r_1$ and $k_1$ is the reaction rate coefficient. The reaction rates are governed by the chemical potentials $\mu_i$~\cite{adame-aranaLiquidPhaseSeparation2020a,bauermannChemicalKineticsMass2022d}
L000161	(see Appendix~\ref{seq:free_energy_and_chempot}),
L000162	\begin{equation}
L000163	    r_1 = k_1\left[ \exp{\frac{\mu_A + \tilde{\delta}(\phi_A, \phi_B)}{k_BT}} - \exp{\frac{\mu_B}{k_BT}} \right]\, , \label{eq:r}
L000164	\end{equation}
L000165	where $k_BT$ is the thermal energy. Moreover, $\tilde{\delta}(\phi_A,\phi_B)$ captures the effects of a composition-dependent fuel~\cite{boekhovenDissipativeSelfAssemblyMolecular2010,boekhovenTransientAssemblyActive2015} that enhances the forward reaction pathway, where $\exp\{ \tilde \delta/(k_BT)\}$ can be understood as a chemostatted fuel activity; see Appendix~\ref{sec:fuel} for further discussions.
L000166	A non-vanishing $\tilde{\delta}(\phi_A,\phi_B)$ breaks detailed balance of the rates, $r_1^\rightharpoonup/r_1^\leftharpoondown = \exp\{(\Delta\mu + \tilde{\delta})/(k_BT)\}$, where $\Delta\mu=\mu_A-\mu_B$ characterizes how far the system is away from chemical equilibrium~\cite{julicherModelingMolecularMotors1997b,weberPhysicsActiveEmulsions2019d}.
L000167	
L000168	
L000169	According to Eq.~\eqref{eq:phi_dot}, the volume fraction fields $\phi_i$ further evolve due to chemical potential gradients in space, leading to diffusive fluxes. In linear response,
L000170	diffusive fluxes read $\bm{j}_i = -\Lambda_i\nabla \mu_i$,
L000171	where $\Lambda_i$ are the mobility coefficients~\cite{de2013non}.
L000172	
L000173	For sufficiently strong interactions between the components, the system can phase-separate, creating  stable inhomogeneous volume-fraction profiles.
L000174	
L000175	The dynamic Eqs.~\eqref{eq:phi_dot} governing phase separation simplify~\cite{bauermannChemicalKineticsMass2022d} when the diffusive exchange rate between phases is much faster than the reaction rate coefficient, $k_1 \ll \Lambda_ik_BT/L^2$, where $L$ is the system size and $\sqrt{\Lambda_ik_BT/k_1}$ is the corresponding reaction-diffusion length scale.
L000176	
L000177	In this limit, the two phases $(\RN{1},\,\RN{2})$ satisfy the conditions of phase equilibrium at all times:
L000178	\begin{equation}
L000179	    \mu_i^\RN{1} = \mu_i^\RN{2}\,. \label{eq:phase_coex}
L000180	\end{equation} Furthermore, each phase is homogeneous in composition with different volume fractions in each phase $(\phi_i^\RN{1},\phi_i^\RN{2})$ with corresponding phase volumes $V^\RN{1}$ and $V^{\RN{2}}=V-V^\RN{1}$. This leads to the simplified  dynamic equations at phase equilibrium~\cite{bauermannChemicalKineticsMass2022d}:
L000181	\begin{subequations}
L000182	\label{eq:kinetic_evolve}
L000183	\begin{align}
L000184	    \dv{\phi_i^{\RN{1}/\RN{2}}}{t} &= r_i^{\RN{1}/\RN{2}} - j^{\RN{1}/\RN{2}}_i - \phi_i^{\RN{1}/\RN{2}}\frac{\dot{V}^{\RN{1}/\RN{2}}}{V^{\RN{1}/\RN{2}}} \, , \label{eq:phi_dot_fast_diff}\\
L000185	    \frac{\dot{V}^{\RN{1}/\RN{2}}}{V^{\RN{1}/\RN{2}}} &= \sum_{k=A,B,C} \left( r_k^{\RN{1}/\RN{2}} - j_k^{\RN{1}/\RN{2}} \right)\, , \label{eq:vol_change}
L000186	\end{align}
L000187	\end{subequations}
L000188	where $i=A,B$, and the diffusive flux $j_i^{\RN{1}/\RN{2}}$ is set to ensure the conditions of phase coexistence (Eq.~\eqref{eq:phase_coex}), see Appendix~\ref{seq:SJ_method} for a derivation. Phase-averaged quantities are denoted by a bar, which, for an arbitrary quantity $X$ at phase equilibrium, is
L000189	\begin{equation}
L000190	    \bar{X} \equiv \frac{V^\RN{1}X^\RN{1} + V^\RN{2}X^\RN{2}}{V^\RN{1} + V^\RN{2}}\,. \label{eq:phase_avg}
L000191	\end{equation}
L000192	For a ternary system with chemical reaction 1 (Eq.~\eqref{eq:r_1_pathway}), a natural choice of quantities is the phase-averaged total volume fraction $\bar{\psi}$, which is conserved during reaction 1, and the phase-averaged reaction extent $\bar{\xi}$,
L000193	\begin{equation}
L000194	    \bar{\psi} \equiv \frac{\bar{\phi}_A+\bar{\phi}_B}{2}\,,\qquad \qquad\quad  \bar{\xi} \equiv \frac{\bar{\phi}_B-\bar{\phi}_A}{2}\,.\label{eq:tot_vol_frac}
L000195	\end{equation}
L000196	With this choice of quantities, Eqs.~\eqref{eq:kinetic_evolve} become
L000197	\begin{equation}
L000198	\label{eq:dt_xi_bar}
L000199	 \text{d}_t\bar{\psi}=0\,,\quad\qquad\qquad \text{d}_t\bar{\xi}=\bar{r}_1   \,.
L000200	\end{equation}
L000201	Steady states, which corresponds to $\bar{r}_1=0$, defines the reaction nullcline of $r_1$:
L000202	\begin{equation}
L000203	    \label{eq:nullcline_condtion}
L000204	 V^\RN{1}\,r^\RN{1}_1 = V^\RN{2}\,r^\RN{2}_1\, .
L000205	\end{equation}
L000206	
L000207	For reactions obeying detailed balance of the rates ($\tilde \delta=0$), the nullcline is the tie-line of the binodal, making it independent of the phase volumes ($V^\RN{1}$ and $V^\RN{2}$). For chemical reactions that break the detailed balance of the rates, the nullcline for phase-separated systems depends on the phase volumes. To maintain the system away from equilibrium,
L000208	we consider
L000209	\begin{equation}
L000210	\label{eq:delta_tilde}
L000211	\tilde{\delta}(\psi) = \frac{\delta}{\pi}\left[\frac{\pi}{2} + \tanh{\left(\frac{\psi-\psi_{1/2}}{\kappa}\right)}\right]
L000212	\, ,
L000213	\end{equation}
L000214	where
L000215	$\delta\geq 0$ is the fuel strength that enhances turnover from $A$ to $B$. For $\delta=0$, the system can settle to thermodynamic equilibrium.
L000216	
L000217	The parameter $\kappa\ll 1$
L000218	sets the range of $\psi$-values around $\psi_{1/2}$ where the transition from non-fueled to the fueled case occurs.
L000219	For $\psi_{1/2}$ inside the binodal, the dilute phase is  approximately unfueled, while the dense phase is   fueled  ($\tilde{\delta}^\RN{1}\simeq 0$, $\tilde{\delta}^\RN{2}\simeq \delta$), resulting in a volume-dependent reaction nullcline when phase-separated.
L000220	The phase-dependent fueling gives rise to non-equilibrium steady states (NESS) with continuous chemical turnover in both phases, balanced by diffusive fluxes across the phase boundary, see Fig.~\ref{fig:1}(a). For the fueling described by Eq.~\eqref{eq:delta_tilde}, the component $B$ is produced in the dense phase (large $\psi$) and diffuses to the dilute phase (small $\psi$), reacting to $A$ before diffusing back to the droplet.
L000221	Eq.~\eqref{eq:nullcline_condtion}
L000222	dictates a corresponding steady state droplet volume
L000223	\begin{equation}
L000224	    \frac{V^\RN{2}}{V} = \frac{k_1^\RN{1}\left[e^{\frac{\Delta\mu+\delta^\RN{1}}{k_BT}} - 1 \right]}{k_1^\RN{2}\left[e^{\frac{\Delta\mu+\delta^\RN{2}}{k_BT}} - 1\right] -  k_1^\RN{1}\left[e^{\frac{\Delta\mu+\delta^\RN{1}}{k_BT}} - 1 \right] } \, ,  \label{eq:NESS}
L000225	\end{equation}
L000226	where $\delta^\text{I/II}=\tilde{\delta}(\psi^\text{I/II})$ and $k_1^\text{I/II}$ denote the phase dependent reaction rate coefficients of reaction 1 (Eq.~\eqref{eq:r_1_pathway}).
L000227	Unless stated otherwise, we solve Eqs.~\eqref{eq:kinetic_evolve} numerically.
L000228	
L000229	For information about the parameters used and numerical implementation, see Appendix~\ref{seq:parameters_used}.
L000230	
L000231	
L000232	\textit{Pitchfork bifurcation to an active droplet:}
L000233	Without fuel ($\delta=0$), the steady state of the system is homogeneous, corresponding to thermodynamic equilibrium.
L000234	Upon increasing the fuel strength
L000235	$\delta$, active droplets emerge as non-equilibrium steady states that are locally stable.
L000236	Their emergence requires a large enough fueling, bending the reaction nullcline strong enough (Fig.~\ref{fig:2}(a,b)) and thereby creating multiple intersections with the same conserved line of constant total volume fraction $\bar{\psi}$.
L000237	We note that the homogeneous steady state remains stable as $\delta$ is increased and a locally stable active droplet is created. Thus, the system becomes bistable with two locally stable steady states.
L000238	
L000239	Bistability between an active droplet state and a homogeneous state emerges  through a pitchfork bifurcation at which the steady droplet volume $V^\RN{2}$ jumps from zero to a finite value;
L000240	see Fig.~\ref{fig:2}(c).
L000241	The bifurcation occurs at a critical fuel strength $\delta^*$. An approximate expression for the critical fuel strength is given as (see Appendix~\ref{sec:analytics} for the derivation)
L000242	\begin{equation}
L000243	    \delta^* \simeq k_BT \log{\left( 1 + \frac{k^\RN{1}_1}{k^\RN{2}_1}\Theta \right) } \, , \label{eq:ana_deltastar}
L000244	\end{equation}
L000245	where $\Theta$ depends solely on thermodynamic parameters (see Eq.~\eqref{eq:crit_interactions}). We see that the bifurcation is favored when the reactions are faster in the dense phase compared to the dilute phase ($k^\RN{2}_1 > k^\RN{1}_1$).
L000246	Moreover, the prerequisite for the bifurcation ($\Theta>0$) sets a restriction to certain phase diagram types.
L000247	For example, the bifurcation can occur when the
L000248	 product $B$ of the fueled reaction  is
L000249	less soluble than its precursor $A$, for which $\Theta>0$.
L000250	Furthermore, $\Theta$ never approaches zero implying that fuel is always necessary ($\delta>0$) for the emergence of bistability.
L000251	
L000252	
L000253	
L000254	We further find that bistability is only possible
L000255	in a range of total volume fractions
L000256	$\bar{\psi}$-values and this range increases with fuel strength $\delta$ (orange domain in Fig.~\ref{fig:2}(d,e)).
L000257	The analytic expression for the critical fuel strength $\delta^*$ given in Eq.~\eqref{eq:ana_deltastar} agrees well with the complete numerical solution close to the active droplet domain in Fig.~\ref{fig:2}(e).
L000258	As the total volume fraction $\bar{\psi}$ enters the binodal for a fixed fuel strength $\delta>\delta^*$, a jump occurs in both phase volume and average composition (Fig.~\ref{fig:2}(d)), unlike the case for $\delta < \delta^*$.
L000259	
L000260	The onset of bistability can be understood through a normal form obtained from Taylor expanding the dynamic Eq.~\eqref{eq:dt_xi_bar} for the reaction extent $\bar{\xi}$. By expanding the phase-separated and homogeneous case separately, at the points $(\bar{\xi}_0,\bar{\psi}_0)$ and $(\bar{\xi}_2,\bar{\psi}_0)$ respectively, we find (derivation see Appendix~\ref{sec:effective_bistab}),
L000261	\begin{equation}
L000262	   \partial_t\bar{\xi} \simeq
L000263	\begin{cases}
L000264	-\left(\bar{\xi} - \bar{\xi}_0\right)h_1,\qquad\qquad\qquad\,\,\,\quad \,\bar{\xi} \leq \xi^\RN{1},\\
L000265	 \bar{r}_1(\bar{\xi}_2, \bar{\psi}_0) - \left(\bar{\xi} - \bar{\xi}_2\right)^2\,h_2\quad\qquad \bar{\xi} > \xi^\RN{1}\,,\label{eq:effective_equations}
L000266	\end{cases}
L000267	\end{equation}
L000268	with the coefficients $h_1$ and $h_2$ given in Eq.~\eqref{eq:h_1} and \eqref{eq:h_2} respectively, $\bar{r}_1$ is the phase-averaged reaction rate evaluated at the phase-separated expansion point, and $\xi^\RN{1}$ is the reaction extent at the dilute branch of the binodal for the given $\bar{\psi}_0$. As seen in Fig.~\ref{fig:2}(b), for homogeneous values of the reaction extent ($\bar{\xi}\leq\xi^\RN{1}$), the reaction rate is linear and stable ($h_1>0$) around its steady point $\bar{\xi}_0$. For phase-separated values of the reaction extent ($\bar{\xi}>\xi^\RN{1}$), a second-order expansion is necessary to capture the behaviour for strong fueling $\delta$.
L000269	Since the normal form in the phase-separated domain corresponds to a concave parabola ($h_2>0$), the requirement for bistability is a positive offset value  at the expansion point:
L000270	\begin{equation}
L000271	    \bar{r}_1 = r^\rightharpoonup_1\left(\overline{\exp{\frac{\delta}{k_BT}} - \exp{-\frac{\Delta \mu}{k_BT}}}\right) >0
L000272	    \, .
L000273	    \label{eq:r_bar_rewrite}
L000274	\end{equation}
L000275	This equation shows that the pitchfork bifurcation occurs when the thermodynamic force $(\Delta \mu)$ is dominated by  the non-equilibrium driving $(\delta)$.
L000276	The bar denotes a phase average (Eq.~\eqref{eq:phase_avg}).
L000277	We note that for $\bar{\psi}_0$ values with a homogeneous steady point, the chemical potential difference is negative when phase separated ($\Delta\mu<0$).
L000278	
L000279	
