L000563	\end{comment}
L000564	\begin{equation}
L000565	    \frac{\dot{s}}{k_B} = \frac{\mu_Fk_\text{f}}{k_BT\nu_F}\exp{\frac{\mu_A+\mu_F}{k_BT}} \, .    \label{eq:entropy_prod_rate_homogeneous}
