L000585	\section{Kinetics at phase equilibrium}\label{seq:SJ_method}
L000586	
L000587	In this section, we follow the work of Bauermann et al.~\cite{bauermannChemicalKineticsMass2022d} to derive the expression for the diffusive flux between the two phases, $j_i^{\RN{1}/\RN{2}}$, in Eqs.~\eqref{eq:kinetic_evolve}. This approach to phase-separated kinetics is valid when the system is at phase equilibrium throughout the kinetics, i.e., if the system size $L$ is much smaller than the reaction-diffusion length; $k_1 \ll \Lambda_ik_BT/L^2$. For phase-separated systems, this implies that the concentration profiles of each component in both phases are uniform $\phi_i^{\RN{1}/\RN{2}}$, and the interface is infinitely thin (the $\kappa$-terms in Eq.~\eqref{eq:gibbs_spatial} are ignored).
L000588	
L000589	For two phases to remain at phase coexistence, the chemical potentials of all $M-1$ components in the two phases change equally in time,
L000590	\begin{equation}
L000591	    \partial_t \mu_i^\RN{1} = \partial_t \mu_i^\RN{2}, \label{eq:equal_chem}
L000592	\end{equation}
L000593	and are initiated at equal values of the chemical potentials $\mu_i^\RN{1}(t=0) = \mu_i^\RN{2}(t=0)$, but different compositions. Using the chain rule, the time derivative of a chemical potential can be written as
L000594	\begin{equation}
L000595	     \partial_t \mu_i^\alpha = \sum_{k=1}^M \dot{\phi_k^\alpha}\pdv{\mu_i^\alpha}{\phi_k} \, , \label{eq:mu_dot}
L000596	\end{equation}
L000597	where $\alpha$ is the phase index; $\alpha\in\{\RN{1}, \RN{2}\}$.
L000598	Incompressible systems, where the molecular volumes are independent of composition $\text{d}_t\nu_i=0$, follow Eqs.~\eqref{eq:kinetic_evolve}. Combining Eqs.~\eqref{eq:kinetic_evolve} with the expression for the volume change of the phases (Eq.~\eqref{eq:vol_change}) for volume conserving chemical reaction $(\sum_{i=1}^M r_i=0)$, we obtain
L000599	\begin{equation}
L000600	    \dot{\phi_k^\alpha} = r_k^{\alpha} - j_k^{\alpha} + \phi_k^{\alpha} \sum_{l=1}^M j_{l}^{\alpha} \, . \label{eq:kinetic_in_app}
L000601	\end{equation}
L000602	Such that the chemical potential change in Eq. \eqref{eq:mu_dot} takes the form
L000603	\begin{equation}
L000604	     \partial_t \mu_i^\alpha = \sum_{k=1}^M \left( r_k^{\alpha} - j_k^{\alpha}  + \phi_k^{\alpha} \sum_{l=1}^M j_l^{\alpha} \right)\pdv{\mu_i^\alpha}{\phi_k}\, ,
L000605	\end{equation}
L000606	which can be expressed in terms of the fluxes:
L000607	\begin{align}
L000608	    \begin{split}
L000609	    \partial_t \mu_i^\alpha &= \sum_{k=1}^M j_k^\alpha\left(-\pdv{\mu_i^\alpha}{\phi_k} + \sum_{l=1}^M \phi_l^\alpha \pdv{\mu_i^\alpha}{\phi_l}\right)+  \sum_{k=1}^M \pdv{\mu_i^\alpha}{\phi_k}r_k^\alpha \, .\end{split}
L000610	\end{align}
L000611	The kinetic constraint on the chemical potentials (Eq.~\eqref{eq:equal_chem}) thus reads
L000612	\begin{align}
L000613	     &\sum_{k=1}^M j_k^\RN{1}\left\{ \sum_{l=1}^M \phi_l^\RN{1} \pdv{\mu_i^\RN{1}}{\phi_l^\RN{1}} -\pdv{\mu_i^\RN{1}}{\phi_k^\RN{1}} + \frac{V^\RN{1}}{V^\RN{2}}\left(\sum_{l=1}^M \phi_l^\RN{2} \pdv{\mu_i^\RN{2}}{\phi_l^\RN{2}} -\pdv{\mu_i^\RN{2}}{\phi_k^\RN{2}} \right) \right\} \nonumber \\ &= -\sum_{k=1}^M \pdv{\mu_i^\RN{1}}{\phi_k^\RN{1}}r_k^\RN{1} +  \sum_{k=1}^M \pdv{\mu_i^\RN{2}}{\phi_k^\RN{2}}r_k^\RN{2} \, ,\label{eq:chem_pot_constraint}
L000614	\end{align}
L000615	where we have used the conservation of particle volume of the diffusive flux,
L000616	\begin{equation}
L000617	    j_i^\RN{1}V^\RN{1} = -j_i^\RN{2}V^\RN{2} \, . \label{eq:particle_cons}
L000618	\end{equation}
L000619	This set of equations \eqref{eq:chem_pot_constraint} can be written as a matrix-vector equation
L000620	\begin{equation}
L000621	    A_{ik}j^\RN{1}_k = s_i,
L000622	\end{equation}
L000623	which can be solved for $j^\RN{1}_k$. The reaction rates in each phase act as source terms in $s_i$, while $A_{ik}$ specifies how the composition changes in each phase will affect the chemical potentials, constraining the diffusive fluxes between the phases to equalize the chemical potential change for all components in both phases.
L000624	
